head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.pageId = "ULDTMS04070";
scwin.storageId = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 중분류 화면 복귀 여부(storageId 파라미터)를 확인해 보관하고 편집기대분류 목록을 조회한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
    try {

                    // 중분류에서 들어온지 여부 체크
                    if (!$c.util.isEmpty($c.data.getParameter("storageId"))) {
                        scwin.storageId = $c.data.getParameter("storageId");
                    }                                             
                    scwin.fnSearch();

    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDTMS04070.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
            /**
             * @method
             * @name btn_excel_onclick
             * @description [엑셀다운로드] 버튼 클릭 — 그리드 데이터를 편집기대분류.xlsx 로 다운로드한다(버튼 컬럼 제외).
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.btn_excel_onclick(e);
             */
            scwin.btn_excel_onclick = function (e) {

                const option = {};
                option.fileName = "편집기대분류.xlsx";
                option.type = "1";
                option.removeColumns = "5";

                $c.data.downloadGridViewExcel(grd_list, option, {});
            };

            /**
             * @method
             * @name btn_insert_onclick
             * @description [대분류 등록] 버튼 클릭 — 편집기대분류 등록 팝업을 열고, 등록 완료(refreshYn "Y") 시 그리드 위치를 반영하며 목록을 재조회한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.btn_insert_onclick(e);
             */
            scwin.btn_insert_onclick = async function (e) {

                const result = await scwin.fnPopUp("편집기대분류 등록", {});
                if (!$c.util.isEmpty(result) && result.refreshYn === "Y") {                    
                    //  그리드 위치 처리
                    if (!$c.util.isEmpty(result.storageId)) {
                        scwin.storageId = result.storageId;
                    }
                    scwin.fnSearch();
                }
            };

            /**
             * @method
             * @name grd_list_oncellclick
             * @description 목록 셀 클릭 — 대분류명(editClssNm) 클릭 시 위치 저장 후 중분류 화면(ULDTMS04090)으로 이동하고, 변경(update) 버튼 클릭 시 변경 팝업을 열어 저장 완료 시 재조회하며, 삭제(delete) 버튼 클릭 시 확인 후 삭제(sbm_del)를 실행한다.
             * @param {Number} rowIndex 클릭한 행 인덱스
             * @param {Number} columnIndex 클릭한 컬럼 인덱스
             * @param {String} columnId 클릭한 컬럼 ID
             * @returns {void}
             * @hidden N
             * @example scwin.grd_list_oncellclick(0, 1, "editClssNm");
             */
            scwin.grd_list_oncellclick = async function (rowIndex, columnIndex, columnId) {

                // 대분류명일 경우 상세 조회
                if (columnId === "editClssNm") {                
                    const url_ = "/ui/TMS/ULDTMS04090.xml";

                    // 위치 정보 저장
                    $c.tms.setKeywordSave(scwin.pageId, grd_list);

                    // 페이지 이동
                    const params = {};
                    params.storageId = scwin.pageId;
                    params.editClssCd = grd_list.getCellData(rowIndex, "editClssCd");
                    params.editClssNm = grd_list.getCellData(rowIndex, "editClssNm");
                    params.editClssEngNm = grd_list.getCellData(rowIndex, "editClssEngNm");
                    params.ldMktTpCd = grd_list.getCellData(rowIndex, "ldMktTpCd");
                    params.ldMktTpNm = grd_list.getCellData(rowIndex, "ldMktTpNm");
                    params.editUseTpNm = grd_list.getCellData(rowIndex, "editUseTpNm");

                    $c.win.moveUrl(url_, params);
                } else if (columnId === "update") {
                    const params = {};                
                    params.editClssCd = dlt_list.getCellData(rowIndex, "editClssCd");                
                    params.ldMktTpCd = dlt_list.getCellData(rowIndex, "ldMktTpCd");
                    params.editUseTpCd = dlt_list.getCellData(rowIndex, "editUseTpCd");
                    params.editClssNm = dlt_list.getCellData(rowIndex, "editClssNm");
                    params.editClssEngNm = dlt_list.getCellData(rowIndex, "editClssEngNm");
                    params.storageId = scwin.pageId;

                    // 위치 정보 저장
                    $c.tms.setKeywordSave(scwin.pageId, grd_list);

                    const result = await scwin.fnPopUp("편집기대분류 변경", params);
                    if (!$c.util.isEmpty(result) &&  result.refreshYn === "Y") {
                        //  그리드 위치 처리
                        if (!$c.util.isEmpty(result.storageId)) {
                            scwin.storageId = result.storageId;
                        }
                        scwin.fnSearch();
                    } else {
                        $c.tms.delKeyword(scwin.pageId);
                    }
                } else if (columnId === "delete") {
                    if (await $c.win.confirm("삭제 하시겠습니까?")) {                     
                        $c.sbm.setAction(sbm_del, "/api/code/edit-upclss/delete/" + dlt_list.getCellData(rowIndex, "editClssCd"));
                        $c.sbm.execute(sbm_del);
                    }
                }
            };

///////// 4. 서브미션 콜백 영역 /////////
            /**
             * @method
             * @name sbm_list_submitdone
             * @description 목록 조회 콜백 — 저장된 그리드 스크롤 위치가 있으면 복원하고, 실패 시 오류 메시지를 알린다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.sbm_list_submitdone(sbmRtn);
             */
            scwin.sbm_list_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {
                    if (!$c.util.isEmpty(scwin.storageId)) {                    
                        const scrollTop = $c.tms.getKeywordSave(scwin.storageId);

                        // 재조회 여부 체크
                        if (!$c.util.isEmpty(scrollTop)) {
                            grd_list.setScrollTop(scrollTop);
                        }
                        scwin.storageId = "";                    
                    }                    
                } else {
                    $c.win.alert(result.message);
                }                               
            };

            /**
             * @method
             * @name sbm_del_submitdone
             * @description 삭제(sbm_del) 콜백 — 성공 시 완료 알림 후 목록을 재조회하고, 실패 시 오류 메시지를 알린다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example (sbm_del ev:submitdone 바인딩으로 자동 호출)
             */
            scwin.sbm_del_submitdone = async function (e) {

                const result = e.responseJSON;
                if (result.success) {
                    await $c.win.alert("삭제 되었습니다.");
                    scwin.fnSearch();
                } else {
                    $c.win.alert(result.message);
                }             
            };

            /**
             * @method
             * @name fnSearch
             * @description 편집기대분류 목록 조회 — 동적 서브미션(executeDynamic)으로 조회 후 콜백(sbm_list_submitdone)을 직접 호출한다.
             * @returns {void}
             * @hidden N
             * @example await scwin.fnSearch();
             */
            scwin.fnSearch = async function () {

                // 코드 정보 조회
                const sbmOptions = {
                    id : "sbm_list",
                    action : "/api/code/edit-upclss",
                    method : "get",
                    target : "dlt_list=body",
                    gridview : "grd_list",
                    processMsg : "조회중..."
                };

                const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
                scwin.sbm_list_submitdone(sbmRtn);
            }

///////// 5. 일반/업무 함수 영역 /////////
            /**
             * @method
             * @name fnButtonUpdateHtml
             * @description 그리드 변경(update) 컬럼 커스텀 포매터 — [변경] 버튼 HTML 을 반환한다.
             * @param {String} data 셀 데이터
             * @param {String} formattedData 포맷 적용된 셀 데이터
             * @param {Number} rowIndex 행 인덱스
             * @param {Number} columnIndex 컬럼 인덱스
             * @returns {String} 버튼 HTML 문자열
             * @hidden N
             * @example (grd_list update 컬럼 customFormatter 바인딩으로 자동 호출)
             */
            scwin.fnButtonUpdateHtml = function (data, formattedData, rowIndex, columnIndex) {

                return "<button class='btn-edit'>변경</button>";
            };

            /**
             * @method
             * @name fnButtonDeleteHtml
             * @description 그리드 삭제(delete) 컬럼 커스텀 포매터 — [삭제] 버튼 HTML 을 반환한다.
             * @param {String} data 셀 데이터
             * @param {String} formattedData 포맷 적용된 셀 데이터
             * @param {Number} rowIndex 행 인덱스
             * @param {Number} columnIndex 컬럼 인덱스
             * @returns {String} 버튼 HTML 문자열
             * @hidden N
             * @example (grd_list delete 컬럼 customFormatter 바인딩으로 자동 호출)
             */
            scwin.fnButtonDeleteHtml = function (data, formattedData, rowIndex, columnIndex) {

                return "<button class='btn-del' style='color:red;'>삭제</button>";
            };

            /**
             * @method
             * @name fnPopUp
             * @description 편집기대분류 등록/변경 팝업(ULDTMS04080)을 연다.
             * @param {String} title 팝업 타이틀
             * @param {Object} params 팝업 전달 파라미터
             * @returns {Promise} openPopup 결과 Promise(팝업 종료 시 전달받는 객체)
             * @hidden N
             * @example const result = await scwin.fnPopUp("편집기대분류 등록", {});
             */
            scwin.fnPopUp = function (title, params) {

                const url_ = "/ui/TMS/ULDTMS04080.xml";
                const options = {
                    id: "ULDTMS04080_POP",
                    popupName: title,
                    width: "680",
                    height: "340",
                    frameModal: "top"
                };
                return $c.win.openPopup(url_, options, params);
            }
